startOnlineMatch(){
  const name = document.getElementById('onlineName').value.trim() || 'Player';
  this.onlineName = name;
  document.getElementById('modeStatus').innerText = '';
  this.connectOnline(name);
}
connectOnline(name){
  if(this.ws){ this.ws.close(); }
  const proto = location.protocol==='https:'?'wss:':'ws:';
  const host = location.hostname || 'localhost';
  this.ws = new WebSocket(`${proto}//${host}:3001`);
  this.ws.onopen = ()=>{
    this.ws.send(JSON.stringify({type:'join', name}));
  };
  this.ws.onmessage = (ev)=>{ this.onWSMessage(JSON.parse(ev.data)); };
  this.ws.onclose = ()=>{ this.ws=null; if(this.running) this.onPlayerEliminated(); };
  this.ws.onerror = (e)=>{ document.getElementById('modeStatus').innerText = 'Connection failed — is the relay running on :3001?'; };
}
```

