onWSMessage(m){
  const t=m.type;
  if(t==='joined'){
    this.myId=m.id; player.id=m.id; player.name=m.name||this.onlineName;
    m.players.forEach(p=>{ if(p.id!==this.myId) this.addRemote(p.id, p); });
    document.getElementById('modeScreen').classList.add('hidden');
    this.running=true; this.state='PLAYING'; this.startTime=performance.now(); startStorm(); game.loop();
  } else if(t==='state'){
    const ids=new Set();
    m.players.forEach(p=>{
      ids.add(p.id);
      if(p.id===this.myId){ /* server echo of my state; ignore for position (client authoritative) */ return; }
      if(!this.remotePlayers[p.id]) this.addRemote(p.id, p);
      else this.remotePlayers[p.id].apply(p);
    });
    // remove leftovers not in snapshot
    for(const id in this.remotePlayers){ if(!ids.has(id)){ this.remotePlayers[id].remove(); delete this.remotePlayers[id]; } }
  } else if(t==='playerJoin'){ if(m.player.id!==this.myId) this.addRemote(m.player.id, m.player); }
  else if(t==='playerLeave'){ if(this.remotePlayers[m.id]){ this.remotePlayers[m.id].remove(); delete this.remotePlayers[m.id]; } }
  else if(t==='shoot'){ if(m.shooterId===this.myId) return; this.remoteShoot(m); }
  else if(t==='damage'){ this.onDamage(m.targetId, m.dmg, m.shooterId); }
  else if(t==='eliminate'){ this.onEliminate(m.targetId, m.shooterId); }
  else if(t==='build'){ if(this.remoteBuilds.has(m.build.id)) return; this.remoteBuilds.add(m.build.id); addBuildMesh(m.build); }
  else if(t==='breakBuild'){ removeBuildById(m.buildId); }
}
