  const pbb = new THREE.Box3().setFromObject(player.mesh);
  if(bb.intersectsBox(pbb)) ok=false;
  if(!ok){ playSFX('break'); return; }
  player.inventory.resources.wood-=cost;
  const data = { id:'lb'+(nextLocalBuildId++), type:player.buildType, x:gx, y:gy, z:gz, rot:player.buildRot, hp:100, mat:'wood', ownerId:player.id };
