    const d=Math.hypot(b.position.x-x, b.position.z-z);
    if(d<maxDist && d<bd){bd=d; best=b;}
  }
  return best;
}
function damageBuild(b, amount, by){
  b.userData.hp-=amount; if(b.userData.hp<0) b.userData.hp=0;
  if(b.userData.hp<=0){
    playSFX('break');
    removeBuildById(b.userData.id);
    if(by===player){ player.inventory.resources.wood+=25; player.updateHotbar(); }
  } else {
    playSFX('hit');
  }
}

