  startOnlineMatch(){
    const name = document.getElementById('onlineName').value.trim() || 'Player';
    this.onlineName = name;
    document.getElementById('modeStatus').innerText = '';
    this.connectOnline(name);
  },
  connectOnline(name){
    if(this.ws){ try{this.ws.close();}catch(e){} }
    const proto = location.protocol==='https:'?'wss:':'ws:';
    const host = location.hostname || 'localhost';
    this.ws = new WebSocket(`${proto}//${host}:3001`);
    this.ws.onopen = ()=>{ this.ws.send(JSON.stringify({type:'join', name})); };
    this.ws.onmessage = (ev)=>{ this.onWSMessage(JSON.parse(ev.data)); };
    this.ws.onclose = ()=>{ this.ws=null; if(this.running){ document.getElementById('modeStatus').innerText='Disconnected from relay.'; this.onPlayerEliminated(); } };
    this.ws.onerror = ()=>{ document.getElementById('modeStatus').innerText = 'Connection failed — ensure the WebSocket relay is running on :3001'; };
  },
  onWSMessage(m){
    const t=m.type;
    if(t==='joined'){
      this.myId=m.id; player.id=m.id;
      m.players.forEach(p=>{ if(p.id!==this.myId) this.addRemote(p.id, p.name||'Player'); });
      document.getElementById('modeScreen').classList.add('hidden');
      this.running=true; this.state='PLAYING'; this.startTime=performance.now();
      startStorm(); game.loop();
    } else if(t==='state'){
      const ids=new Set();
      m.players.forEach(p=>{
        ids.add(p.id);
        if(p.id===this.myId) return;
        if(!this.remotePlayers[p.id]) this.addRemote(p.id, p.name||'Player');
        this.remotePlayers[p.id].apply(p);
      });
      for(const id in this.remotePlayers){ if(!ids.has(id)){ this.remotePlayers[id].remove(); delete this.remotePlayers[id]; } }
    } else if(t==='playerJoin'){
      if(m.player.id!==this.myId) this.addRemote(m.player.id, m.player.name||'Player');
      addKillFeed('SYSTEM', m.player.name||'Player', 'joined the match');
    } else if(t==='playerLeave'){
      if(this.remotePlayers[m.id]){ this.remotePlayers[m.id].remove(); delete this.remotePlayers[m.id]; }
      addKillFeed('SYSTEM','A player','left the match');
    } else if(t==='shoot'){
      if(m.shooterId===this.myId) return;
      remoteShoot(m);
    } else if(t==='damage'){
      applyOnlineDamage(m.targetId, m.dmg, m.shooterId);
    } else if(t==='eliminate'){
      applyOnlineEliminate(m.targetId, m.shooterId);
    } else if(t==='build'){
      if(buildById.has(m.build.id)) return;
      addBuild({id:m.build.id, type:m.build.type, x:m.build.x, y:m.build.y, z:m.build.z, rot:m.build.rot, hp:100, mat:'wood', ownerId:m.build.ownerId});
    } else if(t==='breakBuild'){
      removeBuildById(m.buildId);
    }
  },
  addRemote(id, name){
    if(this.remotePlayers[id]) return;
    const r = new RemotePlayer(id, name);
    this.remotePlayers[id]=r;
  },
};

// ---------------- Remote players (online) ----------------
class RemotePlayer{
  constructor(id, name){
    this.id=id; this.name=name;
    this.mesh = new THREE.Group();
    const body = new THREE.Mesh(new THREE.CapsuleGeometry(14,36,4,8), new THREE.MeshStandardMaterial({color:0xe67e22}));
    const head = new THREE.Mesh(new THREE.SphereGeometry(12,8,8), new THREE.MeshStandardMaterial({color:0xf5d7b0}));
    head.position.y=32;
    body.castShadow=body.receiveShadow=true; head.castShadow=head.receiveShadow=true;
    this.mesh.add(body); this.mesh.add(head);
    this.mesh.position.set(0,60,0);
    this.mesh.userData.owner=this;
    world.add(this.mesh);
    this.nameTag = document.createElement('div');
    this.nameTag.style.position='absolute'; this.nameTag.style.color='#e67e22'; this.nameTag.style.fontWeight='700';
    this.nameTag.style.fontSize='13px'; this.nameTag.style.textShadow='0 2px 6px rgba(0,0,0,1)'; this.nameTag.style.pointerEvents='none';
    this.nameTag.style.whiteSpace='nowrap'; document.getElementById('hud').appendChild(this.nameTag);
    this.nameTag.innerText=name;
    this.pos=new THREE.Vector3(); this.targetPos=new THREE.Vector3();
    this.yaw=0; this.targetYaw=0; this.hp=100; this.shield=0; this.alive=true;
  }
  apply(s){
    this.targetPos.set(s.x,s.y,s.z); this.targetYaw=s.yaw;
    this.hp=s.hp; this.shield=s.shield; this.alive=!!s.alive;
  }
  update(dt){
    this.pos.lerp(this.targetPos, dt*12);
    this.yaw = lerpAngle(this.yaw, this.targetYaw, dt*6);
    this.mesh.position.copy(this.pos);
    this.mesh.rotation.y=this.yaw;
    this.mesh.visible = this.alive;
    const screen=this.mesh.position.clone().add(new THREE.Vector3(0,85,0)).project(camera);
    const nx=(screen.x*0.5+0.5)*innerWidth, ny=(1-(screen.y*0.5+0.5))*innerHeight;
    this.nameTag.style.left=nx+'px'; this.nameTag.style.top=ny+'px';
    this.nameTag.style.opacity=(screen.z>=0&&screen.z<=1&&this.alive)?'1':'0';
  }
  remove(){ world.remove(this.mesh); this.nameTag.remove(); }
}

