// ---------------- Remote players (online) ----------------
class RemotePlayer{
  constructor(id, name){
    this.id=id; this.name=name;
    this.mesh = new THREE.Group();
    const body = new THREE.Mesh(new THREE.CapsuleGeometry(14,36,4,8), new THREE.MeshStandardMaterial({color:0xe67e22}));
    const head = new THREE.Mesh(new THREE.SphereGeometry(12,8,8), new THREE.MeshStandardMaterial({color:0xf5d7b0}));
    head.position.y=32;
    body.castShadow=body.receiveShadow=true; head.castShadow=head.receiveShadow=true;
    this.mesh.add(body); this.mesh.add(head);
    this.mesh.position.set(0,60,0);
    this.mesh.userData.owner=this;
    world.add(this.mesh);
    this.nameTag = document.createElement('div');
    this.nameTag.style.position='absolute'; this.nameTag.style.color='#e67e22'; this.nameTag.style.fontWeight='700';
    this.nameTag.style.fontSize='13px'; this.nameTag.style.textShadow='0 2px 6px rgba(0,0,0,1)'; this.nameTag.style.pointerEvents='none';
    this.nameTag.style.whiteSpace='nowrap'; document.getElementById('hud').appendChild(this.nameTag);
    this.nameTag.innerText=name;
    this.pos=new THREE.Vector3(); this.targetPos=new THREE.Vector3();
    this.yaw=0; this.targetYaw=0; this.hp=100; this.shield=0; this.alive=true;
  }
  apply(s){
    this.targetPos.set(s.x,s.y,s.z); this.targetYaw=s.yaw;
    this.hp=s.hp; this.shield=s.shield; this.alive=!!s.alive;
  }
  update(dt){
    this.pos.lerp(this.targetPos, dt*12);
    this.yaw = lerpAngle(this.yaw, this.targetYaw, dt*6);
    this.mesh.position.copy(this.pos);
    this.mesh.rotation.y=this.yaw;
    this.mesh.visible = this.alive;
    const screen=this.mesh.position.clone().add(new THREE.Vector3(0,85,0)).project(camera);
    const nx=(screen.x*0.5+0.5)*innerWidth, ny=(1-(screen.y*0.5+0.5))*innerHeight;
    this.nameTag.style.left=nx+'px'; this.nameTag.style.top=ny+'px';
    this.nameTag.style.opacity=(screen.z>=0&&screen.z<=1&&this.alive)?'1':'0';
  }
  remove(){ world.remove(this.mesh); this.nameTag.remove(); }
}

function updateRemotePlayers(dt){ Object.values(game.remotePlayers).forEach(r=>r.update(dt)); }
function sendPlayerState(){
  if(!game.ws || game.ws.readyState!==WebSocket.OPEN || !player.alive) return;
  game.ws.send(JSON.stringify({type:'state', id:player.id, x:player.pos.x, y:player.pos.y, z:player.pos.z,
    yaw:player.cameraYaw, cameraYaw:player.cameraYaw, cameraPitch:player.cameraPitch,
    hp:player.hp, shield:player.shield, equipped:player.equipped, weaponAmmo:player.weaponAmmo, alive:true}));
}
function remoteShoot(m){
  const origin = new THREE.Vector3(m.originX, m.originY, m.originZ);
  const dir = new THREE.Vector3(m.dirX, m.dirY, m.dirZ);
  const end = origin.clone().add(dir.multiplyScalar(900));
  const line = new THREE.Mesh(new THREE.BufferGeometry().setFromPoints([origin, end]), new THREE.MeshBasicMaterial({color:0xffaa00}));
  line.scale.setScalar(0.05); world.add(line);
  setTimeout(()=>world.remove(line), 60);
  const r = game.remotePlayers[m.shooterId];
  if(r) playSFX('shoot_ar');
}
function applyOnlineDamage(targetId, dmg, shooterId){
  if(targetId===player.id){
    const shooterName = (game.remotePlayers[shooterId]&&game.remotePlayers[shooterId].name)||'Unknown';
    player.damage(dmg, {nameTag:{innerText:shooterName}});
  } else {
    const r = game.remotePlayers[targetId];
    if(r && r.alive){
      r.hp = Math.max(0, r.hp - dmg);
      showDamageWorld(r.targetPos.clone().add(new THREE.Vector3(0,70,0)), dmg);
      if(r.hp<=0){ r.alive=false; }
    }
  }
  game.checkEnd();
}
function applyOnlineEliminate(targetId, shooterId){
  if(targetId===player.id){
    const shooterName = (game.remotePlayers[shooterId]&&game.remotePlayers[shooterId].name)||'Unknown';
    player.eliminatedBy={nameTag:{innerText:shooterName}};
    game.onPlayerEliminated();
  } else {
    const r = game.remotePlayers[targetId];
    if(r){ r.alive=false; r.mesh.visible=false; }
    const shooterName = (game.remotePlayers[shooterId]&&game.remotePlayers[shooterId].name)||'Unknown';
    addKillFeed(shooterName, 'an opponent');
  }
  game.checkEnd();
}

