input.newString:
.emote-btn:hover{border-color:#5fb8ff;background:#1c2436}
#onlineName:focus{outline:none;border-color:#5fb8ff;box-shadow:0 0 10px rgba(95,184,255,.35)}
.mode-connecting{color:#ffd166;font-weight:700;animation:pulse 1.2s infinite alternate}
@keyframes pulse{to{opacity:.6}}
/* Lobby */
.lobby-tabs{display:flex;gap:8px;margin-bottom:16px;border-bottom:1px solid #2b3140}
.lobby-tab{background:transparent;border:none;color:#9aa7b8;padding:8px 14px;font-size:.9rem;cursor:pointer;border-bottom:2px solid transparent}
.lobby-tab.active{color:#fff;border-bottom-color:#5fb8ff}
.lobby-tab:hover{color:#dfe6f1}
.lobby-section{display:none;animation:fadeIn .3s}
.lobby-section.active{display:block}
@keyframes fadeIn{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}
.friends-list,.shop-list{display:flex;flex-direction:column;gap:10px;max-height:520px;overflow-y:auto;padding-right:4px}
.friend-row,.shop-item{display:flex;align-items:center;gap:14px;padding:12px 14px;background:rgba(20,24,36,.6);border:1px solid #2b3140;border-radius:10px}
.avatar{width:52px;height:52px;border-radius:10px;background:#141826;border:2px solid #2b3140;display:flex;align-items:center;justify-content:center;font-size:24px;flex-shrink:0}
.friend-info{flex:1}
.friend-name{font-weight:700;color:#dfe6f1}
.friend-status{font-size:.75rem;color:#4caf50;margin-top:2px}
.shop-item{border:1px solid #3a3f4a;cursor:pointer}
.shop-item:hover{border-color:#5fb8ff;background:rgba(95,184,255,.06)}
.shop-thumb{width:70px;height:70px;border-radius:8px;background:#141826;border:2px solid #2b3140;display:flex;align-items:center;justify-content:center;font-size:26px;flex-shrink:0}
.shop-info{flex:1}
.shop-name{font-weight:700;color:#dfe6f1}
.shop-desc{font-size:.75rem;color:#9aa7b8;margin-top:2px}
.shop-price{color:#ffd166;font-weight:700}
.btn.purchase{background:linear-gradient(180deg,#2e7d32,#1b5e20)}
.bp-track{display:flex;align-items:center;gap:10px;margin-top:12px}
.bp-level{width:44px;height:44px;border-radius:8px;background:#141826;border:2px solid #2b3140;display:flex;align-items:center;justify-content:center;color:#dfe6f1;font-weight:700;font-size:.9rem}
.settings-list{display:flex;flex-direction:column;gap:12px}
.setting-row{display:flex;align-items:center;justify-content:space-between;padding:12px 14px;background:rgba(20,24,36,.6);border:1px solid #2b3140;border-radius:10px}
.setting-row label{color:#dfe6f1;font-size:.9rem}
.toggle{width:44px;height:24px;background:#2b3140;border-radius:12px;position:relative;cursor:pointer}
.toggle.on{background:#4caf50}
.toggle::after{content:'';position:absolute;top:2px;left:2px;width:20px;height:20px;background:#fff;border-radius:50%;transition:left .2s}
.toggle.on::after{left:22px}
.mini-map-box{width:200px;height:200px;border:2px solid #2b3140;border-radius:10px;background:#0a0c14;margin-top:12px}

