function renderLobbyMinimap(){
  const c=document.getElementById('lobbyMinimap'); if(!c) return;
  const ctx=c.getContext('2d'); const w=c.width, h=c.height;
  ctx.fillStyle='#0a0c14'; ctx.fillRect(0,0,w,h);
  ctx.strokeStyle='#2b3140'; ctx.lineWidth=2; ctx.strokeRect(2,2,w-4,h-4);
  const scale=(w-6)/(CFG.WORLD_HALF*2); const cx=w/2, cy=h/2;
  POIS.forEach(p=>{
    ctx.fillStyle='#5fb8ff'; ctx.beginPath(); ctx.arc(cx+p.pos[0]*scale, cy+p.pos[1]*scale, 2.5, 0, Math.PI*2); ctx.fill();
  });
}
let lobbyRAF;
function lobbyLoop(){
