// Audio (Web Audio API) — synthesized Chapter 4 Season 1 gun & item sounds
const AudioCtx = (window.AudioContext || window.webkitAudioContext);
const audio = new AudioCtx();

function playTone(freq, type='sine', dur=0.08, vol=0.1, when){
  const t = audio.currentTime + (when||0);
  const o = audio.createOscillator(); const g = audio.createGain();
  o.type = type; o.frequency.setValueAtTime(freq, t);
  g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.001, t+dur);
  o.connect(g); g.connect(audio.destination);
  o.start(t); o.stop(t+dur);
}

// noise buffer for gunshot impacts / body shots
const noiseBuf = (()=>{
  const len = audio.sampleRate * 0.12;
  const b = audio.createBuffer(1, len, audio.sampleRate);
  const d = b.getChannelData(0);
  for(let i=0;i<len;i++) d[i] = (Math.random()*2-1) * Math.pow(1-i/len, 2);
  return b;
})();
function playNoise(dur, vol, type='lowpass', freq=600){
  const t = audio.currentTime;
  const n = audio.createBufferSource(); n.buffer = noiseBuf; n.loop = true;
  const f = audio.createBiquadFilter(); f.type = type; f.frequency.value = freq;
  const g = audio.createGain(); g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.001, t+dur);
  n.connect(f); f.connect(g); g.connect(audio.destination);
  n.start(t); n.stop(t+dur);
}
function envelopeShot(g, t, attack, peak, sustain, release){
  g.gain.setValueAtTime(0, t);
  g.gain.linearRampToValueAtTime(peak, t+attack);
  g.gain.linearRampToValueAtTime(sustain, t+attack+0.01);
  g.gain.exponentialRampToValueAtTime(0.001, t+attack+0.01+release);
}

function playSFX(kind){
  if(audio.state==='suspended'){ try{audio.resume();}catch(e){} }
  try{
    const t = audio.currentTime;
    switch(kind){
      // ---------- Gunshots (C4S1 loot pool) ----------
      case 'shoot_ar':{ // Striker AR — crack + body
        const o = audio.createOscillator(); o.type='square'; o.frequency.setValueAtTime(920, t);
        const g = audio.createGain(); envelopeShot(g, t, 0.005, 0.10, 0.02, 0.06);
        o.connect(g); g.connect(audio.destination); o.start(t); o.stop(t+0.07);
        playNoise(0.05, 0.05, 'lowpass', 1400);
      } break;
      case 'shoot_smg':{ // Ranger SMG — rapid snap
        const o = audio.createOscillator(); o.type='square'; o.frequency.setValueAtTime(760, t);
        const g = audio.createGain(); envelopeShot(g, t, 0.003, 0.07, 0.01, 0.05);
        o.connect(g); g.connect(audio.destination); o.start(t); o.stop(t+0.05);
        playNoise(0.04, 0.04, 'highpass', 2200);
      } break;
      case 'shoot_rsmg':{ // Thunder Burst SMG — zippy burst
        const o = audio.createOscillator(); o.type='square'; o.frequency.setValueAtTime(860, t);
        const g = audio.createGain(); envelopeShot(g, t, 0.003, 0.08, 0.015, 0.05);
        o.connect(g); g.connect(audio.destination); o.start(t); o.stop(t+0.055);
        playNoise(0.045, 0.05, 'highpass', 2600);
      } break;
      case 'shoot_sg':{ // Pump Shotgun — heavy boom
        playTone(150,'sawtooth',.14,.15,t);
        playTone(240,'sawtooth',.08,.09,t+.03);
        playNoise(0.18, 0.16, 'lowpass', 700);
      } break;
      case 'shoot_sn':{ // Reaper Sniper — low boom + high crack
        playTone(110,'sawtooth',.2,.18,t);
        const o = audio.createOscillator(); o.type='square'; o.frequency.setValueAtTime(3200, t);
        const g = audio.createGain(); envelopeShot(g, t+.06, 0.005, 0.16, 0.02, 0.1);
        o.connect(g); g.connect(audio.destination); o.start(t+.06); o.stop(t+.16);
        playNoise(0.12, 0.08, 'highpass', 4000);
      } break;
      case 'shoot_pistol':{ // Heisted Pistol — sharp snap
        const o = audio.createOscillator(); o.type='square'; o.frequency.setValueAtTime(1100, t);
        const g = audio.createGain(); envelopeShot(g, t, 0.004, 0.11, 0.02, 0.06);
        o.connect(g); g.connect(audio.destination); o.start(t); o.stop(t+0.06);
        playNoise(0.05, 0.06, 'highpass', 3000);
      } break;
      case 'shoot_hammer':{ // Shockwave Hammer — heavy impact thud
        playTone(90,'sawtooth',.25,.2,t);
        playTone(140,'sine',.2,.12,t+.04);
        playNoise(0.2, 0.14, 'lowpass', 450);
      } break;
      case 'reload': playTone[0]&&(playTone(700,'sine',.07,.09), playTone(900,'sine',.07,.07,.1)); break;
      // ---------- Hits / eliminations ----------
      case 'hit': playNoise(0.06, 0.16, 'highpass', 3500); playTone(1600,'sine',.05,.15); break;
      case 'elim': playTone[0]&&(playTone(1500,'sine',.12,.2,t), playTone(1100,'sine',.12,.16,t+.12), playTone(800,'sine',.2,.14,t+.24)); break;
      // ---------- Building ----------
      case 'build': playTone[0]&&(playTone(950,'sine',.05,.1), playTone(1200,'sine',.05,.06,.07)); break;
      case 'break': playTone(180,'sawtooth',.14,.16); playNoise(0.1,0.12,'lowpass',500); break;
      // ---------- Chests / loot ----------
      case 'chest': playTone[0]&&(playTone(1400,'sine',.1,.14,t), playTone(1800,'sine',.1,.1,t+.08), playTone(2200,'sine',.15,.1,t+.16)); break;
      case 'floorloot': playTone(1100,'sine',.06,.09); break;
      // ---------- Consumables ----------
      case 'slap': playTone[0]&&(playTone(1000,'sine',.09,.16,t), playTone(1300,'sine',.09,.12,t+.1), playNoise(0.08,0.06,'highpass',5000)); break;
      case 'slapberry': playTone[0]&&(playTone(1400,'sine',.06,.14,t), playNoise(0.06,0.05,'highpass',6000)); break;
      case 'heal': playTone[0]&&(playTone(800,'sine',.14,.14,t), playTone(1050,'sine',.14,.12,t+.14), playTone(1300,'sine',.2,.1,t+.28)); break;
      case 'shield': playTone[0]&&(playTone(600,'sine',.14,.14,t), playTone(900,'sine',.14,.12,t+.14), playTone(1200,'sine',.25,.1,t+.28)); break;
      case 'chug': playTone[0]&&(playTone(500,'sine',.16,.14,t), playTone(750,'sine',.16,.12,t+.16), playTone(1100,'sine',.3,.1,t+.32)); break;
      case 'drink': playNoise(0.5, 0.05, 'lowpass', 900); break;
      // ---------- Movement / world ----------
      case 'jump': playTone[0]&&playTone(650,'sine',.07,.08); break;
      case 'land': playTone(180,'sine',.1,.1); break;
      case 'drive': playTone(140,'sine',.12,.05); break;
      case 'storm': playNoise(1.0, 0.04, 'lowpass', 250); break;
    }
  }catch(e){}
}

