const CONSUMABLE_ORDER=['slapberry','slap','shield','med','keg','chugsplash','chug'];
function generateLoot(tier){
  const loot=[];
  const roll=()=>WEAPON_ORDER[Math.floor(Math.random()*WEAPON_ORDER.length)];
  loot.push(roll());
  if(tier==='rare'){ loot.push(roll()); loot.push(roll()); }
  // consumables
  const rollc=()=>CONSUMABLE_ORDER[Math.floor(Math.random()*CONSUMABLE_ORDER.length)];
  if(Math.random()<.6) loot.push(rollc());
  if(tier==='rare' && Math.random()<.5) loot.push(rollc());
  if(Math.random()<.25) loot.push('slapberry');
  return loot;
}
// Floor loot consumables (spawnable items)
const floorConsumables=[];
function dropConsumable(x,z,ctype,y=18){
  const data=CONSUMABLES[ctype];
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(20,16,16), new THREE.MeshStandardMaterial({color: RARITY_COLOR[data.rarity||'common']||0xf1c40f, emissive:0x222222}));
  mesh.position.set(x,y,z); mesh.castShadow=mesh.receiveShadow=true;
  mesh.userData={type:'floorconsumable', ctype, qty:1, pos:mesh.position.clone()};
  world.add(mesh); floorConsumables.push(mesh);
  return mesh;
}
for(let i=0;i<30;i++){
  const ctype=CONSUMABLE_ORDER[Math.floor(Math.random()*CONSUMABLE_ORDER.length)];
  dropConsumable((Math.random()-0.5)*CFG.WORLD_HALF*1.6,(Math.random()-0.5)*CFG.WORLD_HALF*1.6,ctype);
}

