// Swipe gestures on mode picker (left = online, right = ai)
const picker=document.getElementById('modePicker');
let touchStartX=0, touchStartTime=0;
picker.addEventListener('touchstart',e=>{ touchStartX=e.changedTouches[0].clientX; touchStartTime=Date.now(); },{passive:true});
picker.addEventListener('touchend',e=>{
  const dx=e.changedTouches[0].clientX-touchStartX;
  const dt=Date.now()-touchStartTime;
  if(Math.abs(dx)>60 && dt<400){
    playSFX('swipe');
    if(dx<0){ game.selectedMode='online'; } // swipe left -> online
    else if(dx>0){ game.selectedMode='ai'; } // swipe right -> ai
    applyModeSelection();
  }
},{passive:true});
