const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
  const browser=await chromium.launch({args:['--no-sandbox','--disable-setuid-sandbox']});
  const page=await browser.newPage({viewport:{width:1440,height:900}});
  const errors=[];
  page.on('pageerror',e=>errors.push(e.message));
  page.on('console',m=>{if(m.type()==='error')errors.push('[console] '+m.text());});
  await page.goto('http://localhost:3000/',{waitUntil:'load'});
  await page.waitForTimeout(2500);
  await page.screenshot({path:'/tmp/opencode/screenshots/v7_splash.png'});
  await page.click('#btnStart',{force:true});
  await page.click('#cardAI',{force:true});
  await page.click('#btnModeConfirm',{force:true});
  await page.waitForTimeout(900);
  const lobbyVisible=await page.locator('#lobby').evaluate(e=>!e.classList.contains('hidden'));
  await page.screenshot({path:'/tmp/opencode/screenshots/v7_lobby.png'});
  await page.click('#btnLobbyPlay',{force:true});
  await page.waitForTimeout(1200);
  const gameVisible=await page.locator('#lobby').evaluate(e=>e.classList.contains('hidden'));
  await page.screenshot({path:'/tmp/opencode/screenshots/v7_match.png'});
  console.log(JSON.stringify({lobbyVisible,gameVisible,errors:errors.slice(0,12)}));
  await browser.close();
})();

