// Lightweight instanced grass blades bend in the breeze and ripple outward from footsteps.
const grassBladeGeo=new THREE.BufferGeometry();
grassBladeGeo.setAttribute('position',new THREE.Float32BufferAttribute([-.42,0,0,.42,0,0,0,1.8,0],3));
grassBladeGeo.setIndex([0,2,1]);
const grassCount=2600, grassMatrices=new THREE.Object3D();
const grassInstances=new THREE.InstancedMesh(grassBladeGeo,new THREE.MeshBasicMaterial({color:0xffffff,side:THREE.DoubleSide}),grassCount);
grassInstances.frustumCulled=false;
const grassColors=[new THREE.Color(0x5cae36),new THREE.Color(0x83cb43),new THREE.Color(0xa6d64d),new THREE.Color(0x398d35)];
for(let i=0;i<grassCount;i++){
  const x=(Math.random()-.5)*CFG.MAP_SIZE*1.9,z=(Math.random()-.5)*CFG.MAP_SIZE*1.9;
  grassMatrices.position.set(x,.12,z); grassMatrices.rotation.set(0,Math.random()*Math.PI,0); grassMatrices.scale.setScalar(.55+Math.random()*.9); grassMatrices.updateMatrix();
  grassInstances.setMatrixAt(i,grassMatrices.matrix); grassInstances.setColorAt(i,grassColors[Math.floor(Math.random()*grassColors.length)]);
}
grassInstances.material.onBeforeCompile=(shader)=>{
  shader.uniforms.uGrassTime={value:0}; shader.uniforms.uGrassWind={value:0}; shader.uniforms.uFootPos={value:new THREE.Vector3(1e6,0,1e6)}; shader.uniforms.uFootTime={value:-10};
  shader.vertexShader=shader.vertexShader.replace('#include <common>','#include <common>\nattribute mat4 instanceMatrix; uniform float uGrassTime; uniform float uGrassWind; uniform vec3 uFootPos; uniform float uFootTime;');
  shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>',`vec3 transformed = position;\nvec4 worldBlade = modelMatrix * instanceMatrix * vec4(position,1.0);\nfloat footAge = max(0.0, uGrassTime-uFootTime);\nfloat footWave = exp(-footAge*2.7)*exp(-length(worldBlade.xz-uFootPos.xz)*0.035);\nfloat bend = sin(uGrassTime*1.7 + worldBlade.x*0.012 + worldBlade.z*0.009)*uGrassWind + footWave*1.5;\ntransformed.x += bend*position.y*0.55; transformed.z += bend*position.y*0.24;`);
  shader.vertexShader=shader.vertexShader.replace('#include <project_vertex>',`vec4 mvPosition = modelViewMatrix * instanceMatrix * vec4(transformed,1.0);\ngl_Position = projectionMatrix * mvPosition;`);
  grassInstances.userData.grassShader=shader;
