  const sunset=Math.pow(Math.max(0,1-Math.abs(daylight-.42)/.24),2);
  const sky=new THREE.Color(0x17233f).lerp(new THREE.Color(0x83d7ff),Math.pow(daylight,.55)).lerp(new THREE.Color(0xf49a66),sunset*.72);
