  scene.background.copy(sky); scene.fog.color.copy(fog); scene.fog.near=1100; scene.fog.far=lerp(4100,7000,daylight)*(1-weather.rain*.24);
  light.intensity=.22+daylight*1.35; light.color.setRGB(1,lerp(.62,.95,daylight),lerp(.52,.82,daylight));
  light.position.set(Math.cos(phase)*1500,Math.max(180,Math.sin(phase)*1900),600);
  hemiLight.intensity=.28+daylight*.85; ambientLight.intensity=.12+daylight*.2;
