1: /**
2:  * Fortnite Chapter 4 S1 — WebSocket relay server (online multiplayer)
3:  * Runs alongside the static file server on port 3001.
4:  * Authoritative-lite: relays player state, validates shooting/hitscan against
5:  * last-known positions, broadcasts damage/eliminations/build events.
6:  */
7: const WebSocket = require('ws');
8: const http = require('http');
9: 
10: const PORT = Number(process.env.WSS_PORT || 3001);
11: 
12: const server = http.createServer((req, res) => {
13:   res.writeHead(200, { 'Content-Type': 'text/plain' });
14:   res.end('Fortnite WSS relay running');
15: });
16: server.listen(PORT, () => console.log(`[WSS] relay listening on :${PORT}`));
17: 
18: const wss = new WebSocket.Server({ server });
19: 
20: // Config
21: const MAP_HALF = 2300;
22: const PLAYER_RADIUS = 14;
23: const SHOT_RANGE = { ar:900, smg:500, rsmg:560, shotgun:320, sniper:1600, pistol:600, hammer:260 };
24: const SHOT_DMG = { ar:22, smg:14, rsmg:18, shotgun:75, sniper:140, pistol:26, hammer:75 };
25: 
26: const players = new Map(); // id -> playerState
27: const builds = [];         // {id,type,x,y,z,rot,hp,ownerId}
28: let nextBuildId = 1;
29: let nextId = 1;
30: 
31: function randId(){ return 'p' + (nextId++).toString(36) + Date.now().toString(36).slice(-4); }
32: 
33: function newPlayer(id, name){
34:   const angle = Math.random()*Math.PI*2, r = 900 + Math.random()*1600;
35:   return {
36:     id, name,
37:     x: Math.cos(angle)*r, y: 60, z: Math.sin(angle)*r,
38:     yaw: Math.random()*Math.PI*2, cameraYaw: 0, cameraPitch: -0.25,
39:     hp: 100, shield: 0, maxHp: 100, maxShield: 100,
40:     equipped: 'ar', weaponAmmo: 30, alive: true, eliminatedBy: null,
41:     updated: Date.now(),
42:   };
43: }
44: 
45: function clamp(v,a,b){ return v<a?a:v>b?b:v; }
46: function dist2(a,b){ const dx=a.x-b.x, dz=a.z-b.z; return dx*dx+dz*dz; }
47: 
48: function broadcast(obj){
49:   const data = JSON.stringify(obj);
50:   wss.clients.forEach(c => { if (c.readyState === WebSocket.OPEN) c.send(data); });
51: }
52: 
53: function snapshot(){
54:   return { type: 'state', players: Array.from(players.values()).map(p => ({
55:     id:p.id,name:p.name,x:p.x,y:p.y,z:p.z,yaw:p.yaw,cameraYaw:p.cameraYaw,cameraPitch:p.cameraPitch,
56:     hp:p.hp,shield:p.shield,equipped:p.equipped,weaponAmmo:p.weaponAmmo,alive:p.alive,
57:     eliminatedBy:p.eliminatedBy,
58:   })) };
59: }
60: 
61: // ---- Hitscan (server authoritative) ----
62: function hitscan(shooter, origin, dir, weapon){
63:   const range = SHOT_RANGE[weapon] || 900;
64:   const dmg = SHOT_DMG[weapon] || 20;
65:   let best = null, bestD = range*range;
66:   // ray-box vs each other player (simple capsule approximated by box + radius)
67:   const end = { x: origin.x + dir.x*range, y: origin.y + dir.y*range, z: origin.z + dir.z*range };
68:   for (const [id, p] of players){
69:     if (!p.alive || id === shooter.id) continue;
70:     // closest point on segment to player center
71:     const ax = origin.x, ay = origin.y, az = origin.z;
72:     const bx = end.x, by = end.y, bz = end.z;
73:     const px = p.x, py = p.y, pz = p.z;
74:     const abx = bx-ax, aby = by-ay, abz = bz-az;
75:     const apx = px-ax, apy = py-ay, apz = pz-az;
76:     const abab = abx*abx + aby*aby + abz*abz;
77:     let t = abx*apx + aby*apy + abz*apz;
78:     if (abab > 0) t /= abab;
79:     t = clamp(t, 0, 1);
80:     const cx = ax + abx*t, cy = ay + aby*t, cz = az + abz*t;
81:     const d2 = (cx-px)**2 + (cy-py)**2 + (cz-pz)**2;
82:     if (d2 < bestD && d2 < (PLAYER_RADIUS+10)**2){
83:       bestD = d2; best = p;
84:     }
85:   }
86:   return { hit: !!best, target: best, dmg };
87: }
88: 
89: function applyDamage(targetId, dmg, shooterId){
90:   const target = players.get(targetId);
91:   if (!target || !target.alive) return false;
92:   target.hp = clamp(target.hp - dmg, 0, 100);
93:   if (target.hp <= 0){
94:     target.alive = false; target.eliminatedBy = shooterId;
95:     broadcast({ type: 'eliminate', targetId, shooterId });
96:   } else {
97:     broadcast({ type: 'damage', targetId, dmg, shooterId });
98:   }
99:   return true;
100: }
101: 
102: wss.on('connection', (ws, req) => {
103:   const ip = req.socket.remoteAddress;
104:   let myId = null;
105:   console.log(`[WSS] connect ${ip}`);
106: 
107:   ws.on('message', (raw) => {
108:     let msg;
109:     try { msg = JSON.parse(raw); } catch { return; }
110:     const t = msg.type;
111: 
112:     if (t === 'join'){
113:       myId = randId();
114:       const name = (msg.name && String(msg.name).slice(0, 16)) || 'Player';
115:       const p = newPlayer(myId, name);
116:       players.set(myId, p);
117:       ws.send(JSON.stringify({ type: 'joined', id: myId, players: Array.from(players.values()) }));
118:       broadcast({ type: 'playerJoin', player: p });
119:       broadcast(snapshot());
120:       console.log(`[WSS] ${name} joined as ${myId}`);
121:       return;
122:     }
123:     if (!myId) return; // not joined yet
124: 
125:     const p = players.get(myId);
126:     if (!p) return;
127: 
128:     if (t === 'state'){
129:       // update my transform/status from client (client sends, server relays)
130:       const now = Date.now();
131:       p.x = clamp(Number(msg.x)||p.x, -MAP_HALF+60, MAP_HALF-60);
132:       p.y = Number(msg.y)||p.y;
133:       p.z = clamp(Number(msg.z)||p.z, -MAP_HALF+60, MAP_HALF-60);
134:       p.yaw = Number(msg.yaw)||p.yaw;
135:       p.cameraYaw = Number(msg.cameraYaw)||p.cameraYaw;
136:       p.cameraPitch = clamp(Number(msg.cameraPitch)||p.cameraPitch, -1.1, 0.5);
137:       p.hp = clamp(Number(msg.hp)||p.hp, 0, 100);
138:       p.shield = clamp(Number(msg.shield)||p.shield, 0, 100);
139:       p.equipped = msg.equipped || p.equipped;
140:       p.weaponAmmo = Number(msg.weaponAmmo)||p.weaponAmmo;
141:       p.alive = msg.alive !== false;
142:       p.updated = now;
143:     }
144: 
145:     if (t === 'shoot' && p.alive){
146:       const origin = { x: Number(msg.originX)||p.x, y: Number(msg.originY)||(p.y+45), z: Number(msg.originZ)||p.z };
147:       const dir = { x: Number(msg.dirX)||0, y: Number(msg.dirY)||0, z: Number(msg.dirZ)||1 };
148:       const weapon = msg.weapon || p.equipped;
149:       const res = hitscan(p, origin, dir, weapon);
150:       // broadcast tracer so others see it
151:       broadcast({ type: 'shoot', shooterId: myId, originX: origin.x, originY: origin.y, originZ: origin.z,
152:         dirX: dir.x, dirY: dir.y, dirZ: dir.z, weapon });
153:       if (res.hit){
154:         applyDamage(res.target.id, res.dmg, myId);
155:       }
156:       // local ammo handled by client; server trusts weaponAmmo from state
157:     }
158: 
159:     if (t === 'build' && p.alive){
160:       const b = { id: msg.clientId || ('b' + (nextBuildId++)), type: msg.type || 'wall', x: Number(msg.x), y: Number(msg.y), z: Number(msg.z), rot: Number(msg.rot)||0, hp: 100, ownerId: myId };
161:       builds.push(b);
162:       broadcast({ type: 'build', build: b, clientId: msg.clientId || null });
163:     }
164: 
165:     if (t === 'breakBuild'){
166:       const idx = builds.findIndex(b => b.id === msg.buildId);
167:       if (idx >= 0){
168:         builds.splice(idx, 1);
169:         broadcast({ type: 'breakBuild', buildId: msg.buildId });
170:       }
171:     }
172:   });
173: 
174:   ws.on('close', () => {
175:     if (myId){
176:       players.delete(myId);
177:       broadcast({ type: 'playerLeave', id: myId });
178:       broadcast(snapshot());
179:       console.log(`[WSS] ${myId} disconnected`);
180:     }
181:   });
182:   ws.on('error', () => {});
183: });
184: 
185: // Periodic full-state broadcast + storm
186: setInterval(() => {
