const { spawn } = require('node:child_process');
const WebSocket = require('ws');
const port = 3317;
const server = spawn(process.execPath, ['server/wss.js'], { env: { ...process.env, WSS_PORT: String(port) }, stdio: 'ignore' });
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
function connect(name) {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(`ws://127.0.0.1:${port}`);
    const messages = [];
    ws.on('message', raw => {
      const msg = JSON.parse(raw);
      messages.push(msg);
      if (msg.type === 'joined') resolve({ ws, messages, joined: msg });
    });
    ws.on('error', reject);
    ws.on('open', () => ws.send(JSON.stringify({ type: 'join', name })));
  });
}
function until(client, predicate, timeout = 2500) {
  if (client.messages.some(predicate)) return Promise.resolve(client.messages.find(predicate));
  return new Promise((resolve, reject) => {
    const start = Date.now();
    const poll = () => {
      const found = client.messages.find(predicate);
      if (found) return resolve(found);
      if (Date.now() - start > timeout) return reject(new Error('timed out waiting for relay message'));
      setTimeout(poll, 15);
    };
    poll();
  });
}
(async () => {
  try {
    await sleep(250);
    const a = await connect('Alpha');
    const spawnA = a.joined.players.find(p => p.id === a.joined.id);
    if (!spawnA || !Number.isFinite(spawnA.x) || !Number.isFinite(spawnA.z)) throw new Error('joined omitted assigned spawn');
    const b = await connect('Bravo');
    a.ws.send(JSON.stringify({ type:'state', x:0, y:60, z:0, yaw:0, cameraYaw:0, cameraPitch:0, hp:77, shield:0, equipped:'ar', weaponAmmo:30, alive:true }));
    const state = await until(b, m => m.type === 'state' && m.players.some(p => p.id === a.joined.id && p.hp === 77));
    const p = state.players.find(p => p.id === a.joined.id);
    if (p.x !== 0 || p.z !== 0 || p.cameraYaw !== 0 || p.cameraPitch !== 0 || p.shield !== 0) throw new Error(`zero-valued state was not preserved: ${JSON.stringify(p)}`);
    a.ws.send(JSON.stringify({ type:'build', shape:'floor', x:120, y:60, z:-120, rot:0, clientId:`lb-${a.joined.id}-1` }));
    const build = await until(b, m => m.type === 'build' && m.build && m.build.ownerId === a.joined.id);
    if (build.build.type !== 'floor' || build.build.x !== 120 || build.build.z !== -120) throw new Error(`build relay malformed: ${JSON.stringify(build)}`);
    console.log('online relay smoke test passed:', { spawnReceived: true, zeroCoordinatesPreserved: true, buildShape: build.build.type });
    a.ws.close(); b.ws.close();
  } catch (error) {
    console.error(error);
    process.exitCode = 1;
  } finally {
    server.kill('SIGTERM');
  }
})();
