62: // ---- Hitscan (server authoritative) ----
63: function hitscan(shooter, origin, dir, weapon){
64:   const range = SHOT_RANGE[weapon] || 900;
65:   const dmg = SHOT_DMG[weapon] || 20;
66:   let best = null, bestD = range*range;
67:   // ray-box vs each other player (simple capsule approximated by box + radius)
68:   const end = { x: origin.x + dir.x*range, y: origin.y + dir.y*range, z: origin.z + dir.z*range };
69:   for (const [id, p] of players){
70:     if (!p.alive || id === shooter.id) continue;
71:     // closest point on segment to player center
72:     const ax = origin.x, ay = origin.y, az = origin.z;
73:     const bx = end.x, by = end.y, bz = end.z;
74:     const px = p.x, py = p.y, pz = p.z;
75:     const abx = bx-ax, aby = by-ay, abz = bz-az;
76:     const apx = px-ax, apy = py-ay, apz = pz-az;
77:     const abab = abx*abx + aby*aby + abz*abz;
78:     let t = abx*apx + aby*apy + abz*apz;
79:     if (abab > 0) t /= abab;
80:     t = clamp(t, 0, 1);
81:     const cx = ax + abx*t, cy = ay + aby*t, cz = az + abz*t;
82:     const d2 = (cx-px)**2 + (cy-py)**2 + (cz-pz)**2;
83:     if (d2 < bestD && d2 < (PLAYER_RADIUS+10)**2){
84:       bestD = d2; best = p;
85:     }
86:   }
87:   return { hit: !!best, target: best, dmg };
88: }
