90: function applyDamage(targetId, dmg, shooterId){
91:   const target = players.get(targetId);
92:   if (!target || !target.alive) return false;
93:   target.hp = clamp(target.hp - dmg, 0, 100);
94:   if (target.hp <= 0){
95:     target.alive = false; target.eliminatedBy = shooterId;
96:     broadcast({ type: 'eliminate', targetId, shooterId });
97:   } else {
98:     broadcast({ type: 'damage', targetId, dmg, shooterId });
99:   }
