72: function hitscan(shooter, origin, dir, weapon){
73:   const stats = WEAPON_STATS[weapon];
74:   if (!stats) return { hit:false, target:null, dmg:0 };
75:   const { range, damage:dmg } = stats;
76:   let best = null, bestD = range*range;
77:   // ray-box vs each other player (simple capsule approximated by box + radius)
78:   const end = { x: origin.x + dir.x*range, y: origin.y + dir.y*range, z: origin.z + dir.z*range };
79:   for (const [id, p] of players){
80:     if (!p.alive || id === shooter.id) continue;
81:     // closest point on segment to player center
82:     const ax = origin.x, ay = origin.y, az = origin.z;
83:     const bx = end.x, by = end.y, bz = end.z;
84:     const px = p.x, py = p.y, pz = p.z;
85:     const abx = bx-ax, aby = by-ay, abz = bz-az;
86:     const apx = px-ax, apy = py-ay, apz = pz-az;
87:     const abab = abx*abx + aby*aby + abz*abz;
88:     let t = abx*apx + aby*apy + abz*apz;
89:     if (abab > 0) t /= abab;
90:     t = clamp(t, 0, 1);
91:     const cx = ax + abx*t, cy = ay + aby*t, cz = az + abz*t;
92:     const d2 = (cx-px)**2 + (cy-py)**2 + (cz-pz)**2;
93:     if (d2 < bestD && d2 < (PLAYER_RADIUS+10)**2){
94:       bestD = d2; best = p;
95:     }
