const { spawn } = require('child_process');
const WebSocket = require('ws');
const port = 39128;
const server = spawn(process.execPath, ['server/wss.js'], { env: { ...process.env, WSS_PORT: String(port) }, stdio: 'ignore' });
const fail = (err) => { console.error(err); server.kill(); process.exit(1); };
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
(async () => {
  try {
    await sleep(250);
    const a = new WebSocket(`ws://127.0.0.1:${port}`), b = new WebSocket(`ws://127.0.0.1:${port}`);
    await Promise.all([new Promise((r,j)=>{a.once('open',r);a.once('error',j)}),new Promise((r,j)=>{b.once('open',r);b.once('error',j)})]);
    const messages=[]; for(const ws of [a,b]) ws.on('message', raw => messages.push(JSON.parse(raw)));
    a.send(JSON.stringify({type:'join',name:'A'})); b.send(JSON.stringify({type:'join',name:'B'}));
    await sleep(100);
    const joinedA=messages.find(m=>m.type==='joined' && m.players.some(p=>p.name==='A'));
    const joinedB=messages.find(m=>m.type==='joined' && m.players.some(p=>p.name==='B'));
    if(!joinedA||!joinedB) throw Error('join missing');
    const shooter=joinedA.id, target=joinedB.id;
    a.send(JSON.stringify({type:'state',x:0,y:60,z:0,hp:100,shield:0,equipped:'ar',weaponAmmo:30,alive:true}));
    b.send(JSON.stringify({type:'state',x:100,y:60,z:0,hp:100,shield:20,equipped:'ar',weaponAmmo:30,alive:true}));
    await sleep(80);
    a.send(JSON.stringify({type:'shoot',originX:0,originY:60,originZ:0,dirX:1,dirY:0,dirZ:0,weapon:'ar'}));
    await sleep(100);
    const hit=messages.find(m=>m.type==='damage'&&m.targetId===target);
    if(!hit||hit.hp!==90||hit.shield!==0) throw Error(`expected 90 hp/0 shield; got ${JSON.stringify(hit)}`);
    console.log('relay smoke passed: shield absorbed 20, AR applied remaining 10 to HP');
    a.close(); b.close(); await sleep(50); server.kill();
  } catch(e) { fail(e); }
})();
