function remoteShoot(m){
  const origin = new THREE.Vector3(m.originX, m.originY, m.originZ);
  const dir = new THREE.Vector3(m.dirX, m.dirY, m.dirZ);
  const end = origin.clone().add(dir.multiplyScalar(WEAPONS[m.weapon]?.range||900));
  const line = new THREE.Mesh(new THREE.BufferGeometry().setFromPoints([origin, end]), new THREE.MeshBasicMaterial({color:0xffaa00}));
  line.scale.setScalar(0.05); world.add(line);
  setTimeout(()=>world.remove(line), 60);
  const r = game.remotePlayers[m.shooterId];
  if(r) playSFX(weaponSfx(m.weapon));
}
function applyOnlineDamage(targetId, dmg, shooterId, hp, shield){
  if(targetId===player.id){
    player.hp=hp??Math.max(0,player.hp-Math.max(0,dmg-(player.shield||0)));
    if(shield!==undefined) player.shield=shield;
    else player.shield=Math.max(0,player.shield-Math.max(0,dmg));
    showDamage(player.mesh.position.clone().add(new THREE.Vector3(0,70,0)), dmg);
    player.updateHotbar();
  } else {
    const r = game.remotePlayers[targetId];
    if(r && r.alive){
      r.hp = hp??Math.max(0,r.hp-dmg);
      if(shield!==undefined) r.shield=shield;
      showDamageWorld(r.targetPos.clone().add(new THREE.Vector3(0,70,0)), dmg);
      if(r.hp<=0){ r.alive=false; }
    }
  }
  game.checkEnd();
}

