  fortbuxEarned: 0,
  completeQuest(id){
    const q = this.quests.find(q=>q.id===id);
    if(!q || q.completed) return;
    q.progress = Math.min(q.progress + 1, q.target);
    document.getElementById('questsList').innerHTML = '';
    this.quests.forEach(qq=>{
      const el = document.createElement('div');
      el.style = `color: ${qq.progress>=qq.target?'#4caf50':'#9aa7b8'}; font-size:.78rem;`;
      el.innerHTML = `<span style="color:#5fb8ff">✓</span> ${qq.desc}: ${qq.progress}/${qq.target} ${qq.progress>=qq.target?'<span style="color:#ffd166">COMPLETE!</span>':'';
      if(qq.progress>=qq.target){ qq.completed=true; game.fortbuxEarned += qq.reward; document.getElementById('fortbuxEarned').innerText = game.fortbuxEarned; }`;
      document.getElementById('questsList').appendChild(el);
    });
    // Check for fortbux milestone rewards
    if(game.fortbuxEarned >= 15) { alert(`You earned ${game.fortbuxEarned} fortbux! Spend at the Item Shop or Battle Pass!`); }
  },
  resetQuestProgress(){
    this.quests.forEach(q=>{ q.progress=0; q.completed=false; });
    this.fortbuxEarned=0;
    document.getElementById('fortbuxEarned').innerText = 0;
  }
};

