class Entity{
  constructor(id, isBot=false){
    this.id=id; this.isBot=isBot;
    this.mesh = new THREE.Group();
    this.legs=[]; this.arms=[];
    const body = new THREE.Mesh(new THREE.CylinderGeometry(14,14,36,12), new THREE.MeshStandardMaterial({color: isBot?0xe67e22:0x3498db}));
    const head = new THREE.Mesh(new THREE.SphereGeometry(12,8,8), new THREE.MeshStandardMaterial({color:0xf5d7b0}));
    head.position.y=32;
    body.castShadow=body.receiveShadow=true; head.castShadow=head.receiveShadow=true;
    this.mesh.add(body); this.mesh.add(head);
    const limbMat=new THREE.MeshStandardMaterial({color:isBot?0xd35400:0x2874a6,roughness:.72});
    for(const side of [-1,1]){
      const legPivot=new THREE.Group(); legPivot.position.set(side*7,-17,0);
      const leg=new THREE.Mesh(new THREE.CylinderGeometry(4.5,5,21,8),limbMat); leg.position.y=-10.5; leg.castShadow=true; legPivot.add(leg); this.mesh.add(legPivot); this.legs.push(legPivot);
      const armPivot=new THREE.Group(); armPivot.position.set(side*16,9,0);
      const arm=new THREE.Mesh(new THREE.CylinderGeometry(4,4.5,22,8),limbMat); arm.position.y=-10; arm.castShadow=true; armPivot.add(arm); this.mesh.add(armPivot); this.arms.push(armPivot);
    }
    this.pickaxeGroup=new THREE.Group(); this.pickaxeGroup.position.set(17,7,5);
    const handle=new THREE.Mesh(new THREE.CylinderGeometry(1.3,1.3,27,6),new THREE.MeshStandardMaterial({color:0x9b6b3f})); handle.rotation.z=-.22; handle.position.y=-10;
    const pickHead=new THREE.Mesh(new THREE.BoxGeometry(15,4,4),new THREE.MeshStandardMaterial({color:0xc9d2d9,metalness:.65,roughness:.35})); pickHead.position.set(2,3,0);
    this.pickaxeGroup.add(handle,pickHead); this.mesh.add(this.pickaxeGroup);
    this.mesh.position.set(0, 60, 0);
    this.mesh.userData.owner=this;
    world.add(this.mesh);
    this.nameTag = document.createElement('div');
    this.nameTag.style.position='absolute'; this.nameTag.style.color='#fff'; this.nameTag.style.fontWeight='700';
    this.nameTag.style.fontSize='13px'; this.nameTag.style.textShadow='0 2px 6px rgba(0,0,0,1)'; this.nameTag.style.pointerEvents='none';
    this.nameTag.style.whiteSpace='nowrap'; document.getElementById('hud').appendChild(this.nameTag);
    this.nameTag.innerText = isBot?('BOT '+id):'YOU';
    this.nameTag.style.color = isBot?'#e67e22':'#5fb8ff';

    this.pos = new THREE.Vector3(0,60,0);
    this.vel = new THREE.Vector3();
    this.yaw = 0;               // body yaw
    this.cameraYaw = 0;         // camera yaw around player
    this.cameraPitch = -0.25;   // camera pitch
    this.hp=100; this.shield=0; this.maxHp=100; this.maxShield=100;
    this.alive=true; this.eliminatedBy=null;
    this.inventory = { weapons:['ar'], consumables:{slap:2, slapberry:3, bandage:2, med:1, small:3, shield:1, chugsplash:1, keg:0, guardian:0}, resources:{wood:100, stone:100, metal:100}, selected:0 };
    this.equipped = 'ar';
    this.ammo = { ar:90, smg:120, maven:32, thunder:32, excaliber:12, pistol:60, hammer:0 };
    this.weaponMagazines = { ar:WEAPONS.ar.ammo };
    this.weaponAmmo = WEAPONS.ar.ammo;
    this.reloadUntil=0; this.reloadStart=0;
    this.lastShot=0; this.lastHit=0;
    this.buildMode=false; this.buildType='wall'; this.buildRot=0;
    this.slapUntil=0;
    this.crouch=false; this.sprint=false;
    this.grounded=false; this.coyote=0;
    this.emoteUntil=0;
    this.inVehicle=false; this.vehicleSeat=null;
    this.buildCooldown=0;
    this.moveState={forward:0,right:0};
    this.animTime=0; this.actionUntil=0; this.actionType=''; this.actionStart=0;
  }
  get speed(){ const base = this.crouch?CFG.CROUCH:(this.sprint?CFG.SPRINT:CFG.WALK); return this.slapUntil>performance.now()? base*1.55: base; }
  get weaponData(){ return WEAPONS[this.equipped]; }
  triggerAction(type, duration){
    const now=performance.now();
    this.actionType=type; this.actionStart=now; this.actionDuration=duration; this.actionUntil=now+duration;
  }
  setWeapon(w){
    if(!WEAPONS[w]) return;
    this.equipped=w;
    if(this.weaponMagazines[w]===undefined) this.weaponMagazines[w]=WEAPONS[w].ammo||0;
    this.weaponAmmo=this.weaponMagazines[w];
    this.reloadUntil=0;
    this.updateHotbar();
  }
  addLoot(item){
    if(WEAPONS[item]){
      if(!this.inventory.weapons.includes(item)) this.inventory.weapons.push(item);
      this.ammo[item] = (this.ammo[item]||0)+ (WEAPONS[item].cap||60);
      if(this.inventory.weapons.length===1) this.setWeapon(item);
    } else if(CONSUMABLES[item]){
      this.inventory.consumables[item] = (this.inventory.consumables[item]||0)+(CONSUMABLES[item].qty||1);
    }
    this.updateHotbar();
  }
  updateHotbar(){
    const hb=document.getElementById('hotbar'); hb.innerHTML='';
