  update(dt, input){
    if(!this.alive) return;
    const now=performance.now();
    const isLocal = this===game.player;
    const grounded = this.grounded;
    this.sprint=!!input.sprint&&!this.crouch;
    // movement input
    let move = new THREE.Vector3(input.forward, 0, input.right);
    if(isLocal){
      const camDir = new THREE.Vector3(); camera.getWorldDirection(camDir); camDir.y=0; camDir.normalize();
      const camRight = new THREE.Vector3().crossVectors(camera.getWorldDirection(new THREE.Vector3(0,1,0)), camDir).normalize();
      move = new THREE.Vector3().addScaledVector(camDir, input.forward).addScaledVector(camRight, input.right);
      move.y=0;
    }
    if(move.lengthSq()>0.0001){
      move.normalize();
      const spd = this.speed;
      const target = new THREE.Vector3(move.x*spd, this.vel.y, move.z*spd);
      this.vel.x = lerp(this.vel.x, target.x, 1-Math.exp(-CFG.FRICTION*dt));
      this.vel.z = lerp(this.vel.z, target.z, 1-Math.exp(-CFG.FRICTION*dt));
      if(isLocal){ this.yaw = Math.atan2(move.x, move.z); }
    } else {
      this.vel.x*=Math.exp(-CFG.FRICTION*dt*1.5); this.vel.z*=Math.exp(-CFG.FRICTION*dt*1.5);
    }
    const j=input.jump; input.jump=false;
    if(grounded && j && this.coyote<=0){ this.vel.y=CFG.JUMP; this.coyote=0.15; playSFX('jump'); this.grounded=false; }
    if(input.crouch && !this.crouch){ this.crouch=true; this.mesh.scale.y=.7; }
    else if(!input.crouch && this.crouch){ this.crouch=false; this.mesh.scale.y=1; }
    // gravity
    this.vel.y-=CFG.GRAVITY*dt;
    // apply with simple AABB vs world height (ground + obstacles sampled)
    const ny = this.pos.y + this.vel.y*dt;
    const groundY = getGroundY(this.pos.x, this.pos.z);
    if(ny < groundY+ (this.crouch?22:30)){
      this.pos.y = groundY+(this.crouch?22:30); this.vel.y=0; this.grounded=true; this.coyote=0;
    } else { this.pos.y=ny; this.grounded=false; if(this.coyote>0) this.coyote-=dt; }
    this.pos.x+=this.vel.x*dt; this.pos.z+=this.vel.z*dt;
    // clamp to map
    this.pos.x=clamp(this.pos.x, -CFG.WORLD_HALF+60, CFG.WORLD_HALF-60);
    this.pos.z=clamp(this.pos.z, -CFG.WORLD_HALF+60, CFG.WORLD_HALF-60);
    this.mesh.position.copy(this.pos);
    // Face camera/move direction and animate the simple pivot-based character rig.
    if(isLocal){ this.mesh.rotation.y = this.cameraYaw; }
    else { this.mesh.rotation.y = this.yaw; }
    const horizontalSpeed=Math.hypot(this.vel.x,this.vel.z);
    const gait=clamp(horizontalSpeed/Math.max(CFG.WALK,1),0,1.8);
    this.animTime+=(gait>0.04?dt*(this.sprint?13:9):dt*2.2);
    const stride=Math.sin(this.animTime)*gait*(this.crouch ? .34 : .72);
    const airborne=this.grounded?0:1;
    this.legs.forEach((pivot,i)=>{
      const side=i===0?-1:1;
      pivot.rotation.x=stride*side-airborne*.25;
      pivot.rotation.z=this.crouch?side*.08:0;
    });
    const pickaxeEquipped=!!(this.weaponData&&this.weaponData.type==='melee');
    const harvesting=this.actionType==='harvest'&&now<this.actionUntil;
    this.pickaxeGroup.visible=pickaxeEquipped||harvesting;
    this.arms.forEach((pivot,i)=>{
      const side=i===0?-1:1;
      pivot.rotation.set(-stride*side*.48,0,side*(this.crouch ? .12 : 0));
    });
    this.pickaxeGroup.rotation.set(0,0,0);
    if(pickaxeEquipped){
      this.arms[1].rotation.x=-.72;
      this.pickaxeGroup.rotation.x=-.18;
    }
    if(now<this.actionUntil){
      const progress=clamp((now-this.actionStart)/Math.max(this.actionDuration,.001),0,1);
      const swing=Math.sin(progress*Math.PI);
      if(this.actionType==='harvest'){
        this.pickaxeGroup.visible=true;
        this.arms[1].rotation.x=-1.05+swing*1.65;
        this.pickaxeGroup.rotation.x=-.25-swing*1.75;
        this.arms[0].rotation.x=-.28;
      } else if(this.actionType==='build'){
        this.arms[0].rotation.x=-.75-swing*.8;
        this.arms[1].rotation.x=-.3-swing*.55;
      } else if(this.actionType==='shoot'){
        this.arms[1].rotation.x=-.62-swing*.28;
        this.arms[0].rotation.x=-.48;
      } else if(this.actionType==='reload'){
        this.arms[0].rotation.x=-.9-swing*.22;
        this.arms[1].rotation.x=-.45;
      }
    }
    // name tag projection
    const screen = this.mesh.position.clone().add(new THREE.Vector3(0,80,0)).project(camera);
    const nx = (screen.x*0.5+0.5)*innerWidth, ny2 = (1-(screen.y*0.5+0.5))*innerHeight;
    this.nameTag.style.left = nx+'px'; this.nameTag.style.top = ny2+'px';
    this.nameTag.style.opacity = screen.z<1 && screen.z>0? '1':'0';
    // weapon bob / recoil
    if(this.reloadUntil>now){ this.mesh.rotation.x = Math.sin(now*0.02)*0.02; }
    this.updateHotbar();
  }
}

